\label{thm1.2}
Let $m: [0, \infty) \to \mathbb C$ be a bounded function which satisfies the following H\"ormander condition
\begin{equation}\label{eq1.1}
\sup_{t>0} \|  \psi(\cdot) m(t\cdot) \|_{W^{s,\infty}(\mathbb R)} < \infty
\end{equation}
for some $s > d/2$ and some non-trivial $\psi \in C_c^\infty(0,\infty)$. Then
\begin{itemize}
\item There exists a constant $C > 0$ such that for every sequence of non-negative potentials $V_k \in L^1_{loc}(\mathbb R^d)$ we  have 
$$ \| \Big(\sum_k |  m(-\Delta + V_k) f_k |^2 \Big)^{\frac{1}{2}} \|_{L^{1,\infty}(\mathbb R^d)} \le C\, \| \Big(\sum_k | f_k |^2\Big)^{\frac{1}{2}} \|_{L^1(\mathbb R^d)}.$$
\item Let $p \in (1, \infty)$. Then the family $\{ m(-\Delta + V), \, 0 \le V \in L^1_{loc}(\mathbb R^d) \}$ is ${\mathcal R}$-bounded on $L^p(\mathbb R^d)$. 
\item Let $p \in (1, \infty)$ and $q \in [\min(p,2), \max(p,2)]$. Then there exists a positive constant $C$ such that for every sequence of nonnegative potentials $V_k \in L^1_{loc}(\mathbb R^d)$ we have
$$ \| \Big(\sum_k | m(-\Delta + V_k) f_k |^q \Big)^{\frac{1}{q}} \|_{L^p(\mathbb R^d)} \le C\, \| \Big(\sum_k | f_k |^q\Big)^{\frac{1}{q}} \|_{L^p(\mathbb R^d)}.$$
\end{itemize}

\label{thm2.1}(\cite{Dziubanski}). 
Let $d \ge 1$, $ p \in (1, 2]$  and let ${\mathcal L} = -\Delta + V$ be a Schr\"odinger operator with a non-negative potential $V \in L^1_{loc}(\mathbb R^d)$. Then the Riesz transform $\nabla {\mathcal L}^{- {{}^{1}\!\!/\!{}_{2}}}$ is bounded on $L^p(\mathbb R^d)$ and we have the estimate 
\begin{equation}\label{eq2.1}
\| \nabla {\mathcal L}^{- {{}^{1}\!\!/\!{}_{2}}} \|_{L^p-L^p} \le 2^{\frac{2-p}{p}} \, \| \nabla (-\Delta)^{- {{}^{1}\!\!/\!{}_{2}}} \|_{L^p-L^p}.
\end{equation}
In particular, the $L^p$-norm of $\nabla {\mathcal L}^{- {{}^{1}\!\!/\!{}_{2}}}$ can be estimated by a constant independent of $d$ and $V$.\\
For $p=1$, one has the following weak type $(1,1)$ estimate
\begin{equation}\label{eq2.1-1}
\| \nabla {\mathcal L}^{- {{}^{1}\!\!/\!{}_{2}}} \|_{L^1-L^{1,\infty}} \le 2 \, \| \nabla (-\Delta)^{- {{}^{1}\!\!/\!{}_{2}}} \|_{L^1-L^{1,\infty}}.
\end{equation}

We recall the following basic  formulas
\begin{equation}\label{eq2.2}
{\mathcal L}^{- {{}^{1}\!\!/\!{}_{2}}} = \frac{2}{\pi} \int_0^\infty (1+ t^2 {\mathcal L})^{-1}\, dt \quad{\rm and} \quad {\mathcal L}^{ {{}^{1}\!\!/\!{}_{2}}} = {\mathcal L} {\mathcal L}^{- {{}^{1}\!\!/\!{}_{2}}} = \frac{2}{\pi} \int_0^\infty [ I - (1+t^2{\mathcal L})^{-1} ] \, \frac{dt}{t^2}.
\end{equation}
One may also replace ${\mathcal L}$ by ${\mathcal L} + \epsilon$ to have an invertible operator and then avoid some domain questions in \eqref{eq2.2}. One proves \eqref{eq2.1} for ${\mathcal L} + \epsilon$ and then let $\epsilon \to 0$. We shall ignore these simple details  in the arguments below.
We also recall the following well known $L^1$-maximal inequalities 
\begin{equation}\label{eq2.3}
\| V u \|_{L^1} \le  \| {\mathcal L} u \|_{L^1} \quad {\rm and } \quad \| \Delta u \|_{L^1} \le 2\,  \| {\mathcal L} u \|_{L^1}.
\end{equation} 
For simplicity of notation, we set ${\mathcal L}_0 = - \Delta$. Following the ideas in \cite{Dziubanski} we estimate the $L^1$-norm of the operator ${\mathcal L}_0^{ {{}^{1}\!\!/\!{}_{2}}} {\mathcal L}^{- {{}^{1}\!\!/\!{}_{2}}}$.  We have 
\begin{eqnarray*}
{\mathcal L}_0^{ {{}^{1}\!\!/\!{}_{2}}} {\mathcal L}^{- {{}^{1}\!\!/\!{}_{2}}} f &=& \frac{2}{\pi} \int_0^\infty [ I - (1+t^2{\mathcal L}_0)^{-1} ] {\mathcal L}^{- {{}^{1}\!\!/\!{}_{2}}} f \, \frac{dt}{t^2}\\
&=& \frac{2}{\pi} \int_0^\infty [  (1+t^2{\mathcal L})^{-1} - (1+t^2{\mathcal L}_0)^{-1} ] {\mathcal L}^{- {{}^{1}\!\!/\!{}_{2}}} f \, \frac{dt}{t^2} +\\
 &&   \frac{2}{\pi} \int_0^\infty [ I - (1+t^2{\mathcal L})^{-1} ] {\mathcal L}^{- {{}^{1}\!\!/\!{}_{2}}} f \, \frac{dt}{t^2}\\
&=& f - Tf
\end{eqnarray*}
with 
$$ Tf = \frac{2}{\pi} \int_0^\infty [  (1+t^2{\mathcal L}_0)^{-1} - (1+t^2{\mathcal L})^{-1} ] {\mathcal L}^{- {{}^{1}\!\!/\!{}_{2}}} f \, \frac{dt}{t^2}.$$
We explicit the difference of the two resolvents in the expression of $Tf$ so that 
$$ Tf =  \frac{2}{\pi} \int_0^\infty [  (1+t^2{\mathcal L}_0)^{-1} V (1+t^2{\mathcal L})^{-1} ] {\mathcal L}^{- {{}^{1}\!\!/\!{}_{2}}} f \, dt.$$
Observe that $T$ is  a positive operator since all the resolvents as well as ${\mathcal L}^{- {{}^{1}\!\!/\!{}_{2}}}$ are positive operators. Hence we can restrict our attention in the estimate of $\| Tf \|_{L^1}$ to nonnegative $f$. Now, for nonnegative $f$,
\begin{eqnarray*}
\| Tf \|_{L^1} &=& \int_{\mathbb R^d} T f(x) \, dx\\
&=& \frac{2}{\pi} \int_0^\infty \int_{\mathbb R^d}   (1+t^2{\mathcal L}_0)^{-1} V (1+t^2{\mathcal L})^{-1}  {\mathcal L}^{- {{}^{1}\!\!/\!{}_{2}}} f(x)\, dx\, dt\\
&\le& \frac{2}{\pi} \int_0^\infty \int_{\mathbb R^d}   V (1+t^2{\mathcal L})^{-1}  {\mathcal L}^{- {{}^{1}\!\!/\!{}_{2}}} f(x)\, dx\, dt\\
&=& \frac{2}{\pi} \int_{\mathbb R^d}   V {\mathcal L}^{-1} \int_0^\infty (1+t^2{\mathcal L})^{-1}  {\mathcal L}^{ {{}^{1}\!\!/\!{}_{2}}} f(x)\, dt\, dx\\
&=& \int_{\mathbb R^d} V {\mathcal L}^{-1} f (x)\, dx.
\end{eqnarray*}
Note that in the third line we used the fact that the resolvent $(1+t^2{\mathcal L}_0)^{-1}$ is a contraction on $L^1(\mathbb R^d)$. We apply the maximal inequality \eqref{eq2.3} to estimate the latest term by $\| f \|_{L^1}$. Thus,
\begin{equation}\label{eq2.4}
\| {\mathcal L}_0^{ {{}^{1}\!\!/\!{}_{2}}} {\mathcal L}^{- {{}^{1}\!\!/\!{}_{2}}} \|_{L^1-L^1} \le 2.
\end{equation} 
The  $L^2$-estimate 
\begin{equation}\label{eq2.4-1}
\| {\mathcal L}_0^{ {{}^{1}\!\!/\!{}_{2}}} {\mathcal L}^{- {{}^{1}\!\!/\!{}_{2}}} \|_{L^2-L^2} \le 1
\end{equation} 
follow readily from the fact that 
\begin{eqnarray*}
\| {\mathcal L}_0^{ {{}^{1}\!\!/\!{}_{2}}} f \|_{L^2}^2 &=& \int_{\mathbb R^d}  | \nabla f |^2 \, dx \\
&\le &  \int_{\mathbb R^d} | \nabla f |^2 \, dx + \int_{\mathbb R^d} V | f |^2 \, dx = \| {\mathcal L}^{ {{}^{1}\!\!/\!{}_{2}}} f \|_{L^2}^2.
\end{eqnarray*}
Hence, by interpolation we have for $p \in [1, 2]$,
\begin{equation}\label{eq2.5}
\| {\mathcal L}_0^{ {{}^{1}\!\!/\!{}_{2}}} {\mathcal L}^{- {{}^{1}\!\!/\!{}_{2}}} \|_{L^p-L^p} \le 2^{\frac{2-p}{p}}.
\end{equation} 
Finally, this estimate together with  the factorisation  $\nabla {\mathcal L}^{- {{}^{1}\!\!/\!{}_{2}}} = \nabla {\mathcal L}_0^{- {{}^{1}\!\!/\!{}_{2}}} {\mathcal L}_0^{ {{}^{1}\!\!/\!{}_{2}}} {\mathcal L}^{- {{}^{1}\!\!/\!{}_{2}}}$ implies both  \eqref{eq2.1} and \eqref{eq2.1-1}.

\label{thm3.1} Suppose that ${\bf V}$ satisfies the above assumptions. For every $t \ge 0$ and ${\bf f} \in L^2(\mathbb R^d, \ell^2)$ the following pointwise inequalities are  satisfied
\begin{equation}\label{eq3.1}
\| e^{-t\mathcal A} {\bf f}(x) \|_{\ell^2} \le e^{-tH} \| {\bf f} \|_{\ell^2}(x) \le  e^{t\Delta} \| {\bf f} \|_{\ell^2}(x).
\end{equation}

The second inequality in \eqref{eq3.1} is a very classical result and hence we confine our discussion to the first domination property. 

The proof is based on criteria for domination of semigroups, see \cite{Ouh96}, \cite{Ouh} or \cite{Ouh05}, Theorem~2.30. Denote by ${\mathfrak b}$ the sesquilinear form of the operator $H$, that is
$$ {\mathfrak b}(u,v) = \sum_{j=1}^d \int_{\mathbb R^d} \partial_j u. {\overline \partial_j v} \, dx + \int_{\mathbb R^d} \lambda_{\bf V} u {\overline v}\, dx$$
for $u, v$  in the domain $ D({\mathfrak b})$ of ${\mathfrak b}$ which given by 
$$D({\mathfrak b}) = \{ u \in W^{1,2}(\mathbb R^d), \ \int_{\mathbb R^d} \lambda_{\bf V} | u |^2 \, dx < \infty \}.$$
In order to apply the domination criteria, we have to prove that 
\begin{enumerate}[\rm (a)]
\item
if ${\bf u}\in D({\mathfrak a})$, then $\| \bf u \|_{\ell^2} \in D(\mathfrak{b})$,
\item
if ${\bf u} \in D(\mathfrak{a})$ and $h \in D(\mathfrak{b})$ is such that $|h|\le\| \bf u \|_{\ell^2} $, then $|h| sign{\bf u}\in D(\mathfrak{a})$ and
\begin{equation}\label{eq3.2}
		\text{Re}\,  \mathfrak{a}({\bf u},|h| sign{\bf u}) \ge \mathfrak{b}(\| \bf u \|_{\ell^2},|h|).
\end{equation}
\end{enumerate}
We recall that $sign{\bf u}(x) = \frac{{ {\bf u}}(x)}{\| \bf u(x) \|_{\ell^2}}$ if ${\bf u}(x)  \not = 0$ and $0$ otherwise. 

The proof of these two properties does not differ much from the scalar case, and hence we will skip some details.

Set for $\epsilon > 0$, ${\bf g}_\epsilon  = | h | \frac{ {\bf u}}{\sqrt{ \| \bf u(x) \|_{\ell^2}^2 + \epsilon}}$. Then 
$$ \partial_j {\bf g}_\epsilon = (\partial_j |h|) \frac{ {\bf u}}{\sqrt{ \| \bf u \|_{\ell^2}^2 + \epsilon}} +  |h| \frac{ \partial_j {\bf u}}{\sqrt{ \| \bf u \|_{\ell^2}^2 + \epsilon}} - |h| \frac{ {\bf u}}{ (\| \bf u \|_{\ell^2}^2 + \epsilon)^{3/2}} \text{Re}\, \langle \partial_j u, u \rangle_{\ell^2}.$$
From this it is easy to see that ${\mathfrak a}({\bf g}_\epsilon, {\bf g}_\epsilon)$ is uniformly bounded with respect to $\epsilon$. Therefore, after extracting a subsequence,  ${\bf g}_\epsilon$ converges weakly in $D({\mathfrak a})$ to some ${\bf v}$. Taking the pointwise limit of ${\bf g}_\epsilon$ shows that $|h| sign{\bf u} = {\bf v} \in D({\mathfrak a})$. The same idea gives the the expression of the partial derivative
$$ \partial_j (|h| sign{\bf u}) = (\partial_j |h|) sign{\bf u} +  |h| \frac{ \partial_j {\bf u}}{{\| \bf u \|_{\ell^2}}}\mathbbm 1_{\{{\bf u} \not= 0\}}  - |h| \frac{ {\bf u}}{ \| \bf u \|_{\ell^2}^3} \mathbbm 1_{\{{\bf u} \not= 0\}} \text{Re}\, \langle \partial_j u, u \rangle_{\ell^2}.$$
Using a similar approximation argument, the weak derivative of ${\| \bf u \|_{\ell^2}}$ for $u \in D({\mathfrak a})$ is given by
$$ \partial_j {\| \bf u \|_{\ell^2}} = \text{Re}\, \langle \partial_j {\bf u}, sign{\bf u} \rangle_{\ell^2}.$$
Putting all this information together, $\text{Re}\,  \mathfrak{a}({\bf u},|h| sign{\bf u})$ is the sum of four terms $T_1, \cdots, T_4$ with
\begin{equation}\label{eq3.3}
T_1 = \text{Re}\, \sum_{j=1}^d \int_{\mathbb R^d}  \langle \partial_j {\bf u}, (\partial_j |h|) sign{\bf u} \rangle_{\ell^2} \, dx = \sum_{j=1}^d \int_{\mathbb R^d} \partial_j {\| \bf u \|_{\ell^2}} \partial_j |h|\, dx.
\end{equation}
The second term satisfies 
\begin{equation}\label{eq3.4}
T_2 =  \sum_{j=1}^d \int_{\mathbb R^d} \| \partial_j{\bf u} \|_{\ell^2}^2 \frac{|h|}{\| \bf u \|_{\ell^2}}\mathbbm 1_{\{{\bf u} \not= 0\}}\, dx.
\end{equation}
Next,
\begin{equation}\label{eq3.5}
T_3 = -  \sum_{j=1}^d \int_{\mathbb R^d}  (\text{Re}\, \langle \partial_j{\bf u}, sign{\bf u} \rangle_{\ell^2} )^2  \frac{|h|}{\| \bf u \|_{\ell^2}}\mathbbm 1_{\{{\bf u} \not= 0\}}\, dx
\end{equation}
and 

\begin{eqnarray}
T_4 &=&  \int_{\mathbb R^d}  \langle {\bf V}{\bf u}, sign{\bf u} |h| \rangle_{\ell^2}\, dx  =  \int_{\mathbb R^d}  \langle {\bf V}{\bf u}, {\bf u} \rangle_{\ell^2} \frac{|h |}{\| \bf u \|_{\ell^2}} \mathbbm 1_{\{{\bf u} \not= 0\}}\, dx \nonumber \\
&\ge& \int_{\mathbb R^d} \lambda_{{\bf V}} {\| \bf u \|_{\ell^2}} | h|\, dx. \label{eq3.6}

\end{eqnarray}
The Cauchy-Schwarz inequality (in $\ell^2$) clearly implies that  $T_2 + T_3 \ge 0$. Therefore, the desired inequality in \eqref{eq3.2} follows from this together with \eqref{eq3.3} and \eqref{eq3.5}.

\label{cor3.2}
We have for all $t > 0$ and a.e. $x, y \in \mathbb R^d$
\begin{equation}\label{eq3.8}
\| {\bf p}(t,x,y) \|_{{\mathcal L}(\ell^2)} \le (4 \pi)^{-\frac{d}{2}}\, t^{-\frac{d}{2}} \exp\{ - \frac{| x- y |^2}{4t} \}.
\end{equation}
Here $|x-y|$ denotes the usual Euclidean distance in $\mathbb R^d$.

\label{cor3.3}
There exist  constants $C$, independent of  ${\bf V}$  such that for all  $z \in \mathbb C$ with $\text{Re}\, z > 0$,
\begin{equation}\label{eq3.9}
\| {\bf p}(z,x,y) \|_{{\mathcal L}(\ell^2)} \le C\, (\text{Re}\, z)^{-\frac{d}{2}} \exp\{ - \, \text{Re}\, \frac{| x- y |^2}{8z} \}.
\end{equation}

As mentioned above, the proof follows the ideas in \cite{Coulhon-Duong}. We give the details in order to convince the reader that the $L^p$-norm of $\nabla {\mathcal A}^{- {{}^{1}\!\!/\!{}_{2}}}$ can be bounded by a constant independent of ${\bf V}$. This fact is important for the proof of Theorem~\ref{thm1.1}.

Clearly 
$$ \| \nabla {\bf f} \|_{L^2(\mathbb R^d, \ell^2)}^2 \le {{\mathfrak a}}({\bf f}, {\bf f}) = \| {\mathcal A}^{ {{}^{1}\!\!/\!{}_{2}}} {\bf f} \|_{L^2(\mathbb R^d, \ell^2)}^2$$
and notice  that it  implies that the range $R({\mathcal A}^{ {{}^{1}\!\!/\!{}_{2}}})$ is dense in $L^2(\mathbb R^d, \ell^2)$. It then follows that 
$\partial_j {\mathcal A}^{- {{}^{1}\!\!/\!{}_{2}}}$, initially  defined on $R({\mathcal A}^{ {{}^{1}\!\!/\!{}_{2}}})$, extends  to a contraction operator on $L^2(\mathbb R^d, \ell^2)$.  
We denote by $\partial_j {\mathcal A}^{- {{}^{1}\!\!/\!{}_{2}}}$ (for $j = 1, \cdots, d$)  this extension.  For the remainder of the proof, it is enough by interpolation to prove the weak type $(1,1)$ estimate.

We start with the formula
$$ \partial_j  {\mathcal A}^{- {{}^{1}\!\!/\!{}_{2}}} = \frac{1}{\sqrt{\pi}} \int_0^\infty \partial_j e^{-t {\mathcal A}}\,  \frac{dt}{\sqrt{t}}.$$
It implies that $\partial_j {\mathcal A}^{- {{}^{1}\!\!/\!{}_{2}}}$ is given by a singular kernel
\begin{equation}\label{eq4.2}
 {\bf K}_j(x,y) = \frac{1}{\sqrt{\pi}} \int_0^\infty \partial_{j,x}  {\bf p}(t,x,y)\,  \frac{dt}{\sqrt{t}}
 \end{equation}
where $\partial_{j,x}$ denotes the partial derivative with respect to the variable $x$. For fixed $r > 0$, observe that
\begin{eqnarray*}
\partial_j {\mathcal A}^{- {{}^{1}\!\!/\!{}_{2}}} e^{- r^2 {\mathcal A}} &=& \frac{1}{\sqrt{\pi}} \int_0^\infty \partial_j e^{-(t+r^2) {\mathcal A}}\,  \frac{dt}{\sqrt{t}}\\
&=&  \frac{1}{\sqrt{\pi}} \int_{r^2}^\infty \partial_j e^{-t {\mathcal A}}\,  \frac{dt}{\sqrt{t}}\\
 &=& \frac{1}{\sqrt{\pi}} \int_0^\infty \partial_j e^{-t {\mathcal A}}\,\mathbbm 1_{\{t > r^2\}}\,  \frac{dt}{\sqrt{t-r^2}}.
 \end{eqnarray*}
 Hence, the kernel ${\bf K}^r_j(x,y)$ of $\partial_j {\mathcal A}^{- {{}^{1}\!\!/\!{}_{2}}} e^{- r^2 {\mathcal A}}$ is given by 
\begin{equation}\label{eq4.3}
 {\bf K}^r_j(x,y) = \frac{1}{\sqrt{\pi}} \int_0^\infty \partial_{j,x}  {\bf p}(t,x,y)\, \mathbbm 1_{\{t > r^2\}}\, \frac{dt}{{\sqrt{t-r^2}}}.
 \end{equation}
According to Proposition~\ref{prop:prop2-1} (property~\ref{prop2-1-2}), once we have proved that there exists a constant $W$, independent of $r$, $y$, $u \in \ell^2$ and ${\bf V}$, such that 
\begin{equation}\label{HO-1}
\int_{|x-y| \ge 2 r} \| {\bf K}_j(x,y)u - {\bf K}^r_j(x,y)u \|_{\ell^2}\, dx \le W\, \| u \|_{\ell^2}
\end{equation}
we can conclude that  $\partial_j  {\mathcal A}^{- {{}^{1}\!\!/\!{}_{2}}}$ is weak type $(1,1)$ and its weak type estimate can be bounded by  $C_1 + C_2 W$ for some constants $C_1, C_2$ independent of ${\bf V}$.\footnote{See the estimates (2.2)-(2.4) in the  proof of Theorem~1.1 in \cite{HO}. The constants $C_1, C_2$ depend only on the constants involved in the Calder\'on-Zygmund decomposition. They are independent of the operator.}

The $L^p$-estimate in the theorem will then follow by interpolation since the $L^2$-norm of  $\partial_j {\mathcal A}^{- {{}^{1}\!\!/\!{}_{2}}}$ is bounded by $1$. Thus, it suffices to prove property \eqref{HO-1}. For this, we use the weighted gradient estimate stated in the lemma below.  \\
Applying \eqref{eq4.2} and \eqref{eq4.3} yields for $\beta > 0$ as in Lemma~\ref{lem-grad-p},
\begin{eqnarray*}
&&  \int_{|x-y| \ge 2 r} \| {\bf K}_j(x,y)u - {\bf K}^r_j(x,y)u \|_{\ell^2}\, dx \\
&=& \frac{1}{\sqrt{\pi}}  \int_{|x-y| \ge 2 r} \| \int_0^\infty \partial_{j,x}{\bf p}(t,x,y)u [ \frac{1}{\sqrt{t}} - \mathbbm 1_{\{t > r^2\}}\, \frac{1}{{\sqrt{t-r^2}}} ]\, dt \|_{\ell^2}\, dx\\
&\le&  \frac{1}{\sqrt{\pi}}  \int_{|x-y| \ge 2 r} \int_0^\infty \| \partial_{j,x}{\bf p}(t,x,y)u \|_{\ell^2}| \frac{1}{\sqrt{t}} - \mathbbm 1_{\{t > r^2\}}\, \frac{1}{{\sqrt{t-r^2}}} |\, dt\, dx\\
&=& \frac{1}{\sqrt{\pi}}  \int_{|x-y| \ge 2 r} \int_0^\infty \| \partial_{j,x}{\bf p}(t,x,y)u \|_{\ell^2}\, e^{\frac{\beta|x-y|^2}{2t}} e^{\frac{-\beta|x-y|^2}{2t}}| \frac{1}{\sqrt{t}} - \mathbbm 1_{\{t > r^2\}}\, \frac{1}{{\sqrt{t-r^2}}} |\, dt\, dx\\
&\le & \frac{1}{\sqrt{\pi}}  \int_0^\infty e^{-\frac{\beta r^2}{t}}  \int_{\mathbb R^d} \| \partial_{j,x}{\bf p}(t,x,y)u \|_{\ell^2}\, e^{\frac{\beta|x-y|^2}{2t}} e^{\frac{-\beta|x-y|^2}{4t}}| \frac{1}{\sqrt{t}} - \mathbbm 1_{\{t > r^2\}}\, \frac{1}{{\sqrt{t-r^2}}} |\, dx\, dt\\
&\le & \frac{1}{\sqrt{\pi}}  \int_0^\infty e^{-\frac{\beta r^2}{t}}  | \frac{1}{\sqrt{t}} - \mathbbm 1_{\{t > r^2\}}\, \frac{1}{{\sqrt{t-r^2}}} | \left( \int_{\mathbb R^d} \| \partial_{j,x}{\bf p}(t,x,y)u \|_{\ell^2}^2\, e^{\frac{\beta|x-y|^2}{t}}\, dx\right)^{ {{}^{1}\!\!/\!{}_{2}}}\\
&& \times \left(  \int_{\mathbb R^d} e^{\frac{-\beta|x-y|^2}{2t}}\, dx \right)^{ {{}^{1}\!\!/\!{}_{2}}}\, dt\\
&\le& C_0\,  \| u \|_{\ell^2} \int_0^\infty e^{-\frac{\beta r^2}{t}}  t^{- {{}^{1}\!\!/\!{}_{2}}} | \frac{1}{\sqrt{t}} - \mathbbm 1_{\{t > r^2\}}\, \frac{1}{{\sqrt{t-r^2}}} |\, dt\\
&\le& W\,  \| u \|_{\ell^2}
\end{eqnarray*}
for some constant $W$ independent of $r$ and ${\bf V}$ since the constants $C$ and $\beta$ from Lemma~\ref{lem-grad-p} are independent of ${\bf V}$. This proves the theorem.

\label{thm6.1}
Let ${\bf V} : \mathbb R^d \to {\mathcal L}(\ell^2)$ be weakly  measurable, locally integrable,  and such that for a.e. $x$, ${\bf V} (x)$ is  symmetric and nonnegative operator on $\ell^2$. 
Let $m: [0, \infty) \to \mathbb C$ be a bounded function such that
\begin{equation}\label{eq666}
 \sup_{t > 0} \|  \phi(\cdot) m(t \cdot)  \|_{W^{s, \infty}} < \infty
\end{equation}
for some $s > \frac{d}{2}$ and a nontrivial function $\phi \in C_c^\infty(0, \infty)$. Then the operator $m({\mathcal A})$ is of weak type $(1,1)$ and bounded on $L^p(\mathbb R^d, \ell^2)$ for all $p \in (1,2)$. Both the weak type $(1,1)$  and $L^p$-norm can be estimated by a constant independent of ${\bf V}$.
